"""Offline monitoring reports. Presence of an admissions term is not approval."""
import json
import subprocess
from collections import Counter
from pathlib import Path
from monitor_registry import ROOT,OUT,read,write
import source_monitor as M


def build():
    registry=read(OUT/'registry.json');rows=registry['urls'];sources={r['id']:r for r in rows}
    baseline=read(OUT/'baseline-results.json');events={e['source_id']:e for e in baseline['events']};queue=read(OUT/'private/baseline-queue.json') if (OUT/'private/baseline-queue.json').exists() else read(OUT/'queue.json')
    programs=read(ROOT/'research/programs-2027-2028.json');universities=read(ROOT/'research/universities-2027-2028.json')
    awaiting=[p for p in programs if p['overall_status']=='REQUIRES_VERIFICATION'];observations=[]
    for p in awaiting:
        matches=[]
        cited=[r for r in rows if any(c['owner']=='program' and c['record_id']==p['id'] for c in r['citations'])]
        for row in cited:
            e=events.get(row['id'],{});hits=e.get('initial_keyword_hits',{})
            relevant={k:v for k,v in hits.items() if k in ('2027/28','bando','call for applications')}
            if relevant:matches.append({'source_id':row['id'],'url':row['url'],'observed_at':e['checked_at'],'passages':relevant,'shared_by_program_count':len({c['record_id'] for c in row['citations'] if c['owner']=='program'}),'meaning':'Initial keyword presence on a cited/shared official page; applicability to this programme has not been verified.'})
        observations.append({'id':p['id'],'program':p['program'],'university_id':p['university_id'],'outcome':'2027/28 marker observed' if any('2027/28' in m['passages'] for m in matches) else 'call-related term only' if matches else 'no retained accessible keyword evidence','observations':matches,'no_automatic_status_change':True})
    write(OUT/'awaiting-keyword-observations.json',observations)
    write(OUT/'awaiting-keyword-flags.json',[{'id':r['id'],'university_id':r['university_id'],'sources':[{'source_id':m['source_id'],'url':m['url'],'checked_at':m['observed_at'],'keyword_flags':{k:k in m['passages'] for k in M.KEYWORDS}} for m in r['observations']]} for r in observations])
    write(OUT/'baseline-summary.json',{k:v for k,v in baseline.items() if k!='events'})
    tiers=Counter(r['tier'] for r in rows);types=Counter(r['type'] for r in rows);content=Counter(r['content_type'] for r in rows)
    gates=[{'id':r['id'],'url':r['url'],'gated_record_count':r['gated_record_count'],'gated_program_count':len({c['record_id'] for c in r['gates'] if c['owner']=='program'}),'gated_university_count':len({c['record_id'] for c in r['gates'] if c['owner']=='university'}),'gates':r['gates']} for r in rows if r['tier']=='A']
    summary={'total_urls':len(rows),'tiers':dict(tiers),'types':dict(types),'content_types':dict(content),'uncited_registry_warnings':sum(not r['citations'] for r in rows),'tier_a_gates':gates,'awaiting_keyword_outcomes':dict(Counter(r['outcome'] for r in observations)),'snapshots_compressed_bytes':sum(p.stat().st_size for p in (OUT/'snapshots').glob('*.gz')),'snapshot_count':len(list((OUT/'snapshots').glob('*.gz'))),'current_git_tracked_snapshot_count':0,'snapshot_policy':'Full snapshots and diffs remain local and ignored. Scheduled Actions persist and upload hashes, flags and metadata only. Local explicit review keeps the last two compressed snapshots. No content enters Git or dist.','schedule':{'A':'Monday 05:17 UTC, minimum 7 days','B':'Day 1 each month 05:31 UTC, minimum one calendar month','C':'Jan/Apr/Jul/Oct day 1 05:43 UTC, minimum three calendar months'},'activation':'Workflow is prepared on the feature branch. GitHub schedule/workflow_dispatch requires the workflow on the default branch (master); no default-branch merge was performed.','runtime':'Real baseline file activity window about 5.2 minutes; future checks vary by server response. Six workers, one request per host, at least 2 seconds after each response (longer robots delay wins); 60-minute fetch budget and 90-minute job timeout.','repository_policy':'Only non-content metadata enters Git. Passages, diffs, human-readable queues and full baseline reports remain local and ignored.'}
    write(OUT/'registry-summary.json',summary)
    ranked=sorted(queue['open'],key=M.priority)[:10];write(OUT/'top-priority-items.json',ranked)
    comparison=read(OUT/'production-comparison.json')
    changed=[f"- `{r['status']}` `{r['path']}`" for r in comparison['files']]
    lines=['# Production comparison before monitoring','','Production: `'+comparison['production_commit']+'`. Pre-monitoring branch tip: `'+comparison['pre_monitoring_tip']+'`. All of `e039301`, `d1d75fe`, `3fab14e`, `900315e` are ancestors.','','Exact Git diff: **'+comparison['diff_stat']+'**.','','All 209 programme records and all 34 university records differ because the decision-support and applicant-route layers were added. No records were added/removed and the availability totals remain 47/159/3. Outside those added layers, the only record changes are:','','- `legacy-007`: unresolved degree/language placeholders become null; status unchanged.','- `discovered-022`: leaked language sentinel becomes null; status unchanged.','- `politecnico-torino`: generic institution link replaces the bachelor-only admissions link.','- `tor-vergata`: institution admissions link replaces the Mechatronics-only link.','','User-visible changes before monitoring: Italy-wide/all-fields wording; honest application/availability badges; historical deadline handling; corrected source presentation; eligibility/cost/logistics fields with sources and cycle labels; strict yes/no counts; typed tuition; optional browser-only applicant profiles; selected-route sorting/CSV/calendar and collapsed Other routes. Permanent dark mode already exists in production. No availability status was promoted.','','## Exact changed-file list','']+changed
    (OUT/'production-comparison.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    lines=['# Official source monitoring — baseline and review','','Monitoring is read-only with respect to admissions data. No new research approval or production deployment. Availability remains 47 confirmed / 159 awaiting / 3 not offered.','','## Registry','','Total **'+str(len(rows))+'** unique official URLs. Tiers: '+', '.join(f'{k}={tiers[k]}' for k in 'ABC')+'. Types: '+', '.join(f'{k}={v}' for k,v in sorted(types.items()))+'. HTML/PDF content counts (including known redirects): '+str(dict(content))+'.',f"{summary['uncited_registry_warnings']} URLs have research references but no direct record citation: build warnings, not silent deletions. Each Tier A URL’s exact record/field gates are in registry-summary.json. Registries retain verification dates separately from monitoring dates and distinguish prior raw-response fingerprints from normalized monitoring fingerprints.",'','## Real Tier A baseline','','All **517** selected URLs were attempted once as logical checks (bounded failure retries within a check). Recorded class totals: '+', '.join(f'{k}: **{v}**' for k,v in baseline['classes'].items())+'. Minor, substantive and new-keyword temporal changes: **0**; this is an initial baseline, not a proof of unchanged content since human review.',f"**377 successful normalized text captures** were retained. Of the 106 broken-class entries, **39 are known broken/policy-denied checks** and **67 are unrecoverable checker outcomes** after a Windows atomic-replace lock. There are **34 recorded blocked checks**. Those 67 are not claimed as broken university pages. A further 176 retained text captures lost their detailed HTTP headers/final-URL metadata; their text and fingerprint survive. **No URL was re-fetched early.**",f"The effective failed/unknown ratio is **{baseline['failure_ratio']:.2%}**, so the required >20% health gate is **FAILED**. The run is not represented as green. The checkpoint writer now retries transient Windows locks and independently saves every URL result; offline crash-recovery tests pass. `baseline-results.json` retains per-URL recovery provenance.",'','The observed attempt/snapshot file window was about **5.2 minutes**. Request-count and total-download counters were not durably saved and remain null; neither was invented. The actual compressed snapshots occupy '+str(summary['snapshots_compressed_bytes'])+' bytes; they are excluded from Git and the website.','','## Ten highest-priority review items','','There was no previous monitoring snapshot. The excerpts below are **initial observed passages**, not fabricated added/removed diffs. Future substantive changes receive exact before/after/context excerpts; fixtures test that path.','']
    for i,item in enumerate(ranked,1):
        hit=item.get('initial_keyword_hits',{});passage=hit.get('2027/28') or next(iter(hit.values()),None) or item.get('error','No retained passage')
        lines += [f"{i}. **{', '.join(item['universities']) or 'Official source'}** — {item['change_class']}; {item['suggested_action']}. [Official page]({item['source_url']}).",'','   ```text','   '+passage.replace('\n','\n   '),'   ```','']
    lines += ['## Awaiting-program keyword observations','','These are leads on a cited or shared admissions page, not confirmations for the named programme. Every one of the 159 awaiting records has an explicit outcome and all retained matching passages in awaiting-keyword-observations.json. Counts: '+str(dict(Counter(r['outcome'] for r in observations)))+'.','','| Stable ID | Programme | Observed lead |','|---|---|---|']
    for r in observations:
        if r['observations']:
            first=next((m for m in r['observations'] if '2027/28' in m['passages']),r['observations'][0]);lines.append(f"| {r['id']} | {r['program'].replace('|','/')} | [{r['outcome']}]({first['url']}) |")
    lines += ['','## Schedule, storage and activation','','- Tier A: Monday 05:17 UTC. Tier B: first day monthly 05:31 UTC. Tier C: first day of January/April/July/October 05:43 UTC. Manual dispatch selects A/B/C/all and never bypasses cadence.','- Six workers globally, one request per host; at least two seconds after the preceding response, with robots Crawl-delay/Request-rate honoured. Redirect targets get their own robots/rate check. No captcha/login bypass, account authentication, persistent cookies or university credentials. Conditional ETag/Last-Modified requests are used when available.','- Maximum 8 MiB response, 150 PDF pages, 1 MiB stored normalized text per snapshot, last two distinct snapshots; 512 MiB downloaded per run, 128 MiB compressed-store publication cap, 60-minute fetch budget, 90-minute job timeout. Oversized/incomplete checks are explicit failures or deferrals.','- Compressed text, per-URL recovery journals and full run state live in a bounded Actions artifact (90-day retention), not Git. Weekly artifacts carry the full monthly/quarterly state forward. Compact cadence metadata and open/closed queues commit only to `monitoring/source-checks`; that branch is disabled in Vercel. No production push or production deployment command exists.','- **Activation remains pending:** GitHub schedules require the workflow on the repository’s default `master` branch. The workflow is prepared in this preview branch; no default/production branch was changed.','- Public pages show only allowlisted monitoring dates, change flags and coverage/failure counts, separately from Last reviewed. Queue items, diffs and snapshots are absent from dist. A first-baseline no-change flag explicitly says earlier changes cannot be assessed.','','## Limits and things not completed','','The real baseline is unhealthy, with 67 unrecoverable HTTP outcomes and 176 retained captures lacking full response metadata. Re-fetching those URLs now would violate the requested minimum interval, so they remain queued until their next due check. Initial keyword presence cannot establish that a call was newly published or applies to a named awaiting programme. The schedule was not activated on master. No factual review, record value, status, deadline, tuition, requirement, record review date, new university, account, user alert or production setting was changed.','','## Verification','','Recorded offline fixtures exercise normalization, meaningful/numeric changes, keyword hits, redirect/broken/blocked handling, robots, rate limits, PDF extraction, conditional requests, cadence, two-version retention, queue resolution/archive, Windows-lock recovery, safe workflow branch and public/private separation. Run all existing research/site checks, browser suites and the new monitor tests.']
    (OUT/'report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    print(json.dumps({'urls':len(rows),'tiers':dict(tiers),'types':dict(types),'awaiting':summary['awaiting_keyword_outcomes'],'snapshots_bytes':summary['snapshots_compressed_bytes']}))


if __name__=='__main__':build()
